{"solution_py":""""Write a deterministic manifest for regular files below a root."""
from __future__ import annotations

import hashlib
import json
import os
import stat
from pathlib import Path


def build_manifest(root: Path, output: Path) -> list[dict[str, object]]:
    root_path = root.resolve()
    output_path = output.resolve()
    rows: list[dict[str, object]] = []

    for directory, dirnames, filenames in os.walk(
        root_path, topdown=True, followlinks=False
    ):
        dirnames[:] = sorted(name for name in dirnames if name != ".git")
        for name in sorted(filenames):
            if name == ".git" or name.endswith(".tmp"):
                continue

            path = Path(directory) / name
            if path.resolve() == output_path:
                continue
            try:
                info = path.lstat()
            except OSError:
                continue
            if not stat.S_ISREG(info.st_mode):
                continue

            digest = hashlib.sha256()
            size = 0
            with path.open("rb") as handle:
                while chunk := handle.read(1024 * 1024):
                    digest.update(chunk)
                    size += len(chunk)

            rows.append(
                {
                    "path": path.relative_to(root_path).as_posix(),
                    "size": size,
                    "sha256": digest.hexdigest(),
                }
            )

    rows.sort(key=lambda row: str(row["path"]))
    content = json.dumps(rows, sort_keys=True, separators=(",", ":")) + "\n"
    output.write_text(content, encoding="utf-8")
    return rows
