{"solution_py":""""Write a deterministic manifest for regular files below a root."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


def build_manifest(root: Path, output: Path) -> list[dict[str, object]]:
    root = root.resolve()
    output = output.resolve()
    rows: list[dict[str, object]] = []

    for path in root.rglob("*"):
        if not path.is_file() or path.resolve() == output:
            continue
        relative = path.relative_to(root)
        if ".git" in relative.parts or path.name.endswith(".tmp"):
            continue
        data = path.read_bytes()
        rows.append(
            {
                "path": relative.as_posix(),
                "size": len(data),
                "sha256": hashlib.sha256(data).hexdigest(),
            }
        )

    rows.sort(key=lambda row: row["path"])
    output.write_text(
        json.dumps(rows, sort_keys=True, separators=(",", ":")) + "\n",
        encoding="utf-8",
    )
    return rows
"}
